function study(){metric(D.metrics);const g=grid(),p=panel('A three-week study chronicle','Day 0 is the planner’s relative start, not today’s calendar date. Select a day to inspect the actual scheduled sessions.','full primary','calendar');g.append(p);const cal=el('div','calendar'),detail=el('div','note','Select a day to inspect its allocation.');detail.setAttribute('aria-live','polite');p.append(cal,detail);const v=F[2].data[0].cells.values,rows=v[0].map((_,i)=>v.map(c=>c[i]));for(let d=0;d<21;d++){const sessions=rows.filter(r=>r[0]==='Day '+d),day=el('div','day'+([6,13,20].includes(d)?' rest':'')+([7,14].includes(d)?' deadline':''));const b=el('button');b.append(el('strong','','Day '+d));b.setAttribute('aria-label','Inspect day '+d);day.append(b);let total=0;sessions.forEach(r=>{total+=parseFloat(r[3])||0;day.append(el('div','session',r[2]||r[1]))});day.append(el('small','',total+' min'));b.onclick=()=>{detail.replaceChildren(el('b','','Day '+d+' · '+total+' minutes'));sessions.forEach(r=>detail.append(el('p','',r.filter(Boolean).join(' · '))))};cal.append(day)}note('Deadlines: Psychology day 7 · Physics day 14 · Calculus day 21. Daily cap 120 minutes; 25-minute sessions; rest days 6, 13 and 20. These are the source planner constraints.',p);figure(g,F[0],'Readiness at the exam','Predicted recall after the plan. Estimates from the memory model, not measured exam outcomes.','wide','readiness');figure(g,F[1],'Time stays within the daily cap','Scheduled minutes from the same planner output.','narrow');figure(g,F[3],'Every review changes the trajectory','Choose a topic. Diamonds mark planned reviews.','full','recall');figure(g,F[4],'Where an extra hour helps','Actual recomputed objective gains from the source what-if engine.','wide','allocation');figure(g,F[5],'The day-3 scenario in detail','Added and displaced sessions; source objective changes retained.','narrow');figure(g,F[6],'Fitting the memory model','Scripted review pairs and fitted stability, not this viewer’s personal history.','full')}
function arcade(){const ev=D.evaluation;const order=['random','greedy','rookie','pro','grandmaster'],names=['Random','Greedy','Rookie · Q','Pro · DQN','Grandmaster · MCTS'];const roster=el('div','agent-roster');root.append(roster);const g=grid(),dist=figure(g,F[3],'The score distributions','Classic 12 × 12 board · fixed evaluation seeds · 500 games per policy, MCTS 50. Histogram counts have unequal denominators.','full primary','evaluation');order.forEach((k,i)=>{const a=el('button','agent');a.type='button';a.setAttribute('aria-pressed','false');a.append(el('span','sprite','■ ■ ■'),el('h3','',names[i]),el('strong','',ev.summary[k].mean),el('small','','mean food score'),el('small','',ev.elo[k]+' ELO · n='+(k==='grandmaster'?ev.mcts_n:ev.n_eval)));a.onclick=async()=>{await dist.promise;const already=a.getAttribute('aria-pressed')==='true';roster.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed','false'));if(!already)a.setAttribute('aria-pressed','true');Plotly.restyle(dist.chart,{visible:order.map((_,j)=>already||j===i)});document.getElementById('status').textContent=already?'All agents compared':names[i]+' evaluation distribution'};roster.append(a)});figure(g,F[0],'Learning from states, learning from pixels','Mean score per 100 training episodes. Training curves are not the held-out evaluation scores.','wide','learning');figure(g,F[1],'Rookie’s rating over training','Checkpoint tournament ELO against the baseline pool.','narrow');figure(g,F[2],'The final ladder','Same evaluation conditions, differing MCTS sample size.','narrow');figure(g,F[4],'Head-to-head outcomes','Row policy beats column policy.','wide','strategy');figure(g,F[5],'How the agents steer','Action shares from runs/moves.json.','full');const game=panel('The playable arena','The actual trained-policy game, restyled for DeepArcade. Use arrow keys or WASD.','full game-panel','arena');g.append(game);const launch=el('button','','Load the playable arena'),gameControls=el('div','controls'),standalone=el('a','','Open the standalone game ↗');standalone.href='game.html';standalone.target='_blank';standalone.rel='noopener';gameControls.append(launch,standalone);game.append(gameControls);launch.onclick=()=>{const frame=el('iframe');frame.title='DeepArcade playable Snake game';frame.setAttribute('sandbox','allow-scripts allow-same-origin');frame.srcdoc=D.game_html;game.append(frame);launch.disabled=true;launch.textContent='Arena loaded below';};note('The playable game uses the repository’s genuine trained policies. MCTS uses 80 simulations per move in the reported evaluation; the browser game adjusts its search budget for responsiveness.')}
function watt(){metric(D.metrics.slice(1));const g=grid();figure(g,F[0],'Shift the load. Keep the work.','Seeded household profile · average day over the trailing 30 days · kW and tariff $/kWh on separate axes.','wide primary','load');const r=panel('Choose an intervention','These are source engine scenarios, not new simulations. Select a row to inspect the recorded monthly estimate.','narrow','scenarios');g.append(r);const controls=el('div','controls');r.append(controls);const ledger=el('div','value-ledger');r.append(ledger);const vals=values(F[6].data[0].y),cats=values(F[6].data[0].x);function show(i){ledger.replaceChildren();const x=el('div');x.style.gridColumn='1/-1';x.append(el('strong','','$'+nfmt(vals[i])),el('span','','estimated monthly bill'));ledger.append(x);const m=D.metrics_raw;const assumptions=['Recorded TOU scenario on the seeded profile.','Same energy service, flexible appliance loads rescheduled under the source constraints.','6 kW rooftop solar, conservative export treatment. One October month is not an annual yield forecast.','30 miles per day, overnight charging.','COP 3.0 heating load; October weather assumptions.'];ledger.append(el('p','caption',assumptions[i]));const context=el('p','caption','The optimizer saves $'+m.opt_savings.toFixed(2)+' on the flexible-load cost component ('+m.opt_cost_before.toFixed(2)+' → '+m.opt_cost_after.toFixed(2)+'), not on the full fixed-charge bill denominator.');ledger.append(context)}control(controls,'Intervention',cats.map(clean),show);show(0);figure(g,F[1],'A forecast, with room for uncertainty','The source cumulative display uses an approximate $0.24/kWh conversion. Forecast totals and bands in the top ledger come from demo/metrics.json.','full','forecast');figure(g,F[2],'When the household uses power','This heatmap measures load in kW. It is not a tariff heatmap.','wide','consumption');figure(g,D.tariff,'The tariff clock','Source Rate 194 marginal-price curve repeated across weekday/weekend rules. Weekday peak 15:00–19:00; $/kWh.','narrow');figure(g,F[3],'The savings ledger','Sequential source waterfall; combined solar savings differ from the standalone solar scenario.','full','savings');figure(g,F[4],'The appliance register','Estimated attribution, not individual appliance meter readings.','wide');figure(g,F[7],'Energy in peak hours','Source peak/off-peak energy shares; energy shares differ from cost shares.','narrow');figure(g,F[5],'Weather and consumption','Association in seeded data; the display’s one-line fit is illustrative and is not a causal result.','full');note(D.metrics_raw.anomaly_text.replace(/\u2014/g,'.'))}
function food(){metric(D.metrics);const g=grid();const map=copy(F[0]);const tr=map.data[0];tr.type='scatter';tr.x=tr.lon;tr.y=tr.lat;tr.mode='markers';tr.marker={size:14,color:tr.marker?.color,colorscale:[[0,T.colors[1]],[1,T.accent]],cmin:.5,cmax:1,colorbar:{title:{text:'Model score'},thickness:10}};delete tr.lat;delete tr.lon;delete tr.subplot;delete tr.hovertemplate;tr.hovertemplate='%{text}<br>Approximate location<extra></extra>';tr.text=values(tr.hovertext).length?tr.hovertext:tr.text;map.layout={xaxis:{title:{text:'Longitude · degrees'},tickformat:'.3f'},yaxis:{title:{text:'Latitude · degrees'},tickformat:'.3f',scaleanchor:'x',scaleratio:1},showlegend:false};figure(g,map,'A campus field map','Offline coordinate map · source pins are jittered around named campus locations. No walking routes or exact event rooms are inferred.','wide primary quest-map','map');const p=panel('Demonstration quest listings','Seeded week of 12–18 Oct 2026. Food is a classifier prediction, not a verified offer.','narrow quest-listings','events');g.append(p);const controls=el('div','controls'),search=el('input');search.type='search';search.placeholder='Search title, club or food…';search.setAttribute('aria-label','Search demonstration events');const lab=el('label','','Search demonstrations');lab.append(search);controls.append(lab);p.append(controls);const watch=el('button','','Show watchlist');watch.setAttribute('aria-pressed','false');controls.append(watch);const list=el('div','event-list');p.append(list);const cols=F[1].data[0].cells.values,rows=cols[0].map((_,i)=>cols.map(c=>c[i]));let only=false;const saved=new Set();try{JSON.parse(localStorage.getItem('quest-watchlist')||'[]').forEach(x=>saved.add(x))}catch{}function render(){list.replaceChildren();const q=search.value.toLowerCase();let count=0;rows.forEach((r,i)=>{if(only&&!saved.has(r[1])||q&&!r.join(' ').toLowerCase().includes(q))return;count++;const e=el('article','event');e.append(el('span','badge','DEMONSTRATION'),el('h3','',r[1]),el('p','',r[2]+' · '+r[3]),el('p','',r[4]+' · timezone not recorded'),el('p','confidence',r[5]+' model probability · EV '+r[6]),el('p','caption','Food terms: '+r[7]));const b=el('button','',saved.has(r[1])?'Remove from watchlist':'Save to watchlist');b.onclick=()=>{saved.has(r[1])?saved.delete(r[1]):saved.add(r[1]);try{localStorage.setItem('quest-watchlist',JSON.stringify([...saved]))}catch{}render()};e.append(b);list.append(e)});if(!count)list.append(el('p','caption',only?'Your watchlist has no matching events. Save a demonstration event to try it.':'No matching demonstration events. Try another search.'));document.getElementById('status').textContent=count+' demonstration listings shown'}watch.onclick=()=>{only=!only;watch.setAttribute('aria-pressed',only);watch.textContent=only?'Show all demonstrations':'Show watchlist';render()};search.oninput=render;render();figure(g,F[2],'How well does the classifier perform?','Held-out labeled text test split. These metrics do not verify event attendance, food availability or current campus coverage.','wide','model');figure(g,F[3],'Does confidence match frequency?','Held-out calibration observations. A probability estimate is not a guarantee.','narrow');figure(g,F[4],'Club activity in the demonstration','Counts within the seeded data only.','wide','activity');figure(g,F[5],'Demonstration timing patterns','This is a seeded activity distribution, not historical measured campus activity.','narrow');note('No live feed is operating in this local snapshot. SB Engaged automation was excluded at your request. Demonstration source URLs are not shown as verified event links. Watchlist changes stay in this browser. Only the source ranked top 15 entries are available in this ranked view.')}
const builders={'neural-cppi':neural,FlowForge:flow,toxicflow:toxic,'efficient-frontier-fc':fc,sukuklab:sukuk,formulaforge:formula,'grind-bandit':grind,studyforge:study,deeparcade:arcade,wattwise:watt,'freefood-radar':food};
window.dashboardValidation={repo:D.repo,complete:false,errors:[]};
try{builders[D.repo]();Promise.all(ready).then(()=>Promise.all(charts.filter(ch=>ch.isConnected).map(ch=>Plotly.Plots.resize(ch)))).then(()=>{window.dashboardValidation.complete=true;document.getElementById('status').textContent='Local snapshot ready · '+charts.length+' interactive charts';document.querySelectorAll('.chart').forEach(n=>n.dataset.rendered='true')}).catch(e=>{window.dashboardValidation.errors.push(e.message);document.getElementById('status').textContent='A chart failed. See the affected panel.'})}catch(e){root.append(el('p','error','This snapshot could not finish loading: '+e.message));window.dashboardValidation.errors.push(e.message);throw e}
let resizeTimer;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>charts.forEach(ch=>{if(ch.isConnected&&ch.offsetWidth)Plotly.Plots.resize(ch)}),150)});
